  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, 800, 500);

  ctx.fillStyle = "#111111";
  ctx.strokeStyle = "#111111";
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.font = "30px Arial";

  // 2H₂ + O₂ → 2H₂O
  ctx.fillText("2", 200, 105);
  ctx.fillText("H", 224, 105);
  ctx.font = "20px Arial";
  ctx.fillText("2", 244, 111);

  ctx.font = "30px Arial";
  ctx.fillText("+", 270, 105);
  ctx.fillText("O", 305, 105);
  ctx.font = "20px Arial";
  ctx.fillText("2", 325, 111);

  ctx.font = "30px Arial";
  ctx.fillText("→", 355, 105);
  ctx.fillText("2", 398, 105);
  ctx.fillText("H", 422, 105);
  ctx.font = "20px Arial";
  ctx.fillText("2", 442, 111);
  ctx.font = "30px Arial";
  ctx.fillText("O", 454, 105);

  hit("equation", 190, 65, 290, 55);

  function atom(label, x, y) {
    ctx.font = "28px Arial";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(label, x, y);
  }

  function singleBond(x1, y1, x2, y2) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  function doubleBond(x1, y1, x2, y2) {
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x1, y1 - 3);
    ctx.lineTo(x2, y2 - 3);
    ctx.moveTo(x1, y1 + 3);
    ctx.lineTo(x2, y2 + 3);
    ctx.stroke();
  }

  function hydrogenMolecule(id, x, y) {
    singleBond(x + 19, y, x + 51, y);
    atom("H", x, y);
    atom("H", x + 70, y);
    hit(id, x - 20, y - 24, 110, 48);
  }

  function oxygenMolecule(id, x, y) {
    doubleBond(x + 20, y, x + 58, y);
    atom("O", x, y);
    atom("O", x + 78, y);
    hit(id, x - 20, y - 24, 120, 48);
  }

  function waterMolecule(id, x, y) {
    singleBond(x + 19, y, x + 50, y);
    singleBond(x + 70, y, x + 101, y);
    atom("H", x, y);
    atom("O", x + 60, y);
    atom("H", x + 120, y);
    hit(id, x - 20, y - 24, 160, 48);
  }

  hydrogenMolecule("reactant-h2-1", 75, 235);
  hydrogenMolecule("reactant-h2-2", 75, 315);
  oxygenMolecule("reactant-o2", 250, 275);

  waterMolecule("product-h2o-1", 495, 235);
  waterMolecule("product-h2o-2", 495, 315);

